"""Generate a dependency-free static website. Run: python build.py"""
from pathlib import Path
from html import escape
import json
import re

ROOT = Path(__file__).resolve().parent
CONFIG = json.loads((ROOT / 'site.json').read_text(encoding='utf-8'))
EMAIL = CONFIG['support_email']
assert re.fullmatch(r'[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+', EMAIL), 'Set a real support_email in site.json'
EMAIL = escape(EMAIL, quote=True)
DATE = escape(CONFIG['effective_date'])
DOMAIN = CONFIG['domain']
assert DOMAIN == 'wavely.prandiel.dev'

def document(title, body, route='', english=False):
    depth = len(route.strip('/').split('/')) if route else 0
    base = '../' * depth or './'
    home = base
    privacy = base + 'privacy/'
    en = base + 'en/privacy/'
    lang = 'en' if english else 'ko'
    legal_label = 'Privacy policy' if english else '개인정보처리방침'
    switch = f'<a href="{privacy}" lang="ko" hreflang="ko">한국어</a>' if english else f'<a href="{en}" lang="en" hreflang="en">English</a>'
    canonical = f'https://{DOMAIN}/' + route
    return f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{escape(title)} · Wavely</title><meta name="description" content="Wavely — Personal Music Curator. 개인용 Windows 음악 편집 앱의 공식 소개와 개인정보처리방침.">
<meta name="theme-color" content="#101214"><link rel="canonical" href="{canonical}">
<link rel="icon" type="image/png" href="{base}icon.png"><link rel="stylesheet" href="{base}styles.css">
<meta property="og:title" content="{escape(title)} · Wavely"><meta property="og:description" content="Personal Music Curator. A private Windows music editing application."><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://{DOMAIN}/icon.png">
</head><body><a class="skip" href="#main">{'Skip to content' if english else '본문으로 건너뛰기'}</a><div class="wrap">
<header class="header"><a class="brand" href="{home}" aria-label="Wavely {'home' if english else '홈'}"><img src="{base}icon.png" width="36" height="36" alt="">Wavely</a>
<nav class="nav" aria-label="{'Main navigation' if english else '주요 메뉴'}"><a class="optional" href="{home}#features">{'Features' if english else '주요 기능'}</a><a href="{privacy}">{legal_label}</a>{switch}</nav></header>
{body.replace('@@BASE@@', base)}
<footer class="footer"><span>Wavely · Personal Music Curator</span><div class="footer-links"><a href="{privacy}">{legal_label}</a><a href="{en}">English</a><a href="mailto:{EMAIL}">{EMAIL}</a></div></footer>
</div></body></html>'''

cards = [
('YouTube에서 시작하기', '음악 영상의 정보를 확인하고 오디오를 가져옵니다. 공식 챕터와 설명란의 타임스탬프로 음악 구간을 찾습니다.'),
('원하는 구간을 정확하게', '챕터별 구간 선택과 파형 편집. 시작·종료 지점, 페이드와 앞뒤 무음을 트랙마다 조정합니다.'),
('나만의 MP3와 MP4', '선택한 트랙을 MP3로 추출하거나 앨범아트를 담은 MP4로 만듭니다. 여러 트랙을 한 번에 출력할 수 있습니다.'),
('일관된 음량으로', 'LUFS 기반 음량 정규화로 트랙의 출력 음량을 맞춥니다. 품질과 출력 위치를 직접 설정합니다.'),
('음악의 정보까지 정리', '제목, 아티스트, 앨범 등 메타데이터를 관리합니다. 로컬 이미지와 영상 프레임으로 앨범아트를 지정합니다.'),
('내 PC에 남는 작업실', '편집 정보와 작업 기록은 로컬 라이브러리에 저장합니다. 로컬 편집과 내보내기에는 Google 계정이 필요하지 않습니다.')]
home = '''<main id="main"><section class="hero" aria-labelledby="title"><div><span class="pill"><span class="dot" aria-hidden="true"></span>개인용 Windows 음악 작업실</span><h1 id="title">Wavely</h1><p class="tagline">Personal Music Curator</p><p class="intro">긴 음악에서 좋아하는 순간을 골라,<br>나만의 라이브러리로.<br>가져오기부터 파형 편집, 정리와 출력까지<br>내 PC에서 이어지는 음악 작업실입니다.</p><div class="actions"><a class="button primary" href="#features">주요 기능 살펴보기 <span aria-hidden="true">↗</span></a><a class="button" href="privacy/">개인정보처리방침</a></div></div><div class="art"><img src="@@BASE@@icon.png" width="256" height="256" alt="Wavely 로고: 연두색 오디오 파형"><span class="art-label">A SPACE FOR YOUR SOUND</span></div></section>
<div class="strip"><span>Rust + Tauri 2</span><span>Windows desktop</span><span>개인용 · 공개 배포 없음</span></div>
<section class="section" id="features"><div class="section-head"><div><span class="eyebrow">Your music, your way</span><h2>음악을 모으는 나만의 방식</h2></div><p>현재 사용할 수 있는 로컬 편집 기능입니다.</p></div><div class="features">'''
for i, (title, desc) in enumerate(cards, 1):
    home += f'<article class="card"><span class="number">0{i}</span><h3>{title}</h3><p>{desc}</p></article>'
home += f'''</div></section><section class="section account" id="google"><div><span class="eyebrow">Google account</span><h2>내 채널로 이어지는 음악</h2><span class="status">YouTube 연동 · 개발 및 검증 중</span></div><div><h3>계정 연결은 YouTube 기능을 위해서만</h3><p>Google OAuth로 사용자의 YouTube 채널과 플레이리스트를 확인하고, 사용자가 선택한 MP4를 일부 공개로 업로드해 플레이리스트에 추가하는 기능을 개발하고 있습니다. 실제 계정 연결과 업로드의 전체 동작 검증은 아직 완료되지 않았습니다.</p><p>연결 시 요청하는 권한은 <code>youtube.force-ssl</code>입니다. 채널 조회, 업로드와 플레이리스트 관리에 사용하며, 이 권한은 YouTube 동영상·댓글·자막 등을 조회·수정·삭제할 수 있는 넓은 권한입니다. Wavely는 설명한 기능 범위에서만 사용합니다.</p><p>인증과 API 통신은 사용자의 PC와 Google 사이에서 이루어집니다. 별도의 Wavely 운영 서버는 없습니다.</p><a href="privacy/">데이터 처리와 연결 해제 방법 <span aria-hidden="true">↗</span></a><p class="note">Wavely는 공개 배포하지 않는 개인용 앱입니다. 이 홈페이지는 서비스 소개와 OAuth 브랜딩·개인정보 안내를 위해 공개하며, 설치 파일은 제공하지 않습니다.</p></div></section>
<section class="section contact"><div><span class="eyebrow">Get in touch</span><h2>Wavely에 관한 문의</h2><p>개인정보, 계정 연결 또는 앱에 관해 문의할 수 있습니다.</p></div><a href="mailto:{EMAIL}">{EMAIL} <span aria-hidden="true">↗</span></a></section></main>'''

KO = [
('적용 범위와 운영자', f'''<p>Wavely의 운영자·개발자(Qualified4, 문의: <a href="mailto:{EMAIL}">{EMAIL}</a>)는 개인용 Windows 음악 편집 앱과 이 소개 홈페이지의 데이터 처리 방식을 아래와 같이 안내합니다. 앱은 공개 배포하지 않습니다. 홈페이지에는 계정 생성, 결제, 광고, 분석·추적 스크립트가 없습니다.</p><p>로컬 편집 기능은 구현되어 있으며, YouTube OAuth·업로드·플레이리스트 기능은 개발 및 검증 중입니다. 아래 계정 연동 설명은 시행일에 확인한 개발 코드의 처리 방식이며, 실제 Google 계정 연결과 업로드의 전체 동작 검증이 끝났다는 뜻은 아닙니다.</p>'''),
('처리하는 정보와 이용 목적', '''<ul><li><strong>Google OAuth 인증:</strong> 사용자가 선택한 Google 계정의 동의를 받아 YouTube API 접근 권한을 얻습니다. Google 비밀번호는 앱이 받지 않습니다. 별도의 Gmail·연락처·Drive 권한을 요청하지 않습니다.</li><li><strong>채널 정보:</strong> YouTube 채널 ID·이름, 연결 상태와 갱신 시각을 저장해 업로드 대상 계정을 표시하고 확인합니다.</li><li><strong>플레이리스트:</strong> ID·제목·공개 범위·항목 수·썸네일 URL과 영상 등록 정보를 조회·저장해 대상 선택과 등록 상태 확인에 사용합니다.</li><li><strong>선택한 영상:</strong> 사용자가 선택한 로컬 MP4 및 제목·설명·태그·공개 범위·아동용 여부 등 업로드 설정을 YouTube로 보냅니다. 일부 공개를 기본으로 하며 실제 공개 상태는 YouTube가 결정할 수 있습니다.</li><li><strong>업로드 기록:</strong> 영상 ID, 채널·트랙 연결 정보, 파일 경로·크기·해시, 처리 상태·전송 진행률·오류·시각 및 플레이리스트 등록 상태를 로컬에 저장합니다. 업로드 재개에 필요한 세션 정보도 처리합니다.</li></ul>'''),
('요청 권한과 인증 정보 보관', '''<p>개발 코드에서 요청하는 범위는 <code>https://www.googleapis.com/auth/youtube.force-ssl</code> 하나입니다. 채널 확인, 플레이리스트 조회, 영상 업로드·상태 조회 및 플레이리스트에 영상 추가에 사용합니다. 이 범위는 YouTube 동영상, 평가, 댓글, 자막 등을 조회·수정·삭제할 수 있는 넓은 권한이며, 읽기 전용이나 업로드 전용 권한이 아닙니다. Wavely는 위에 설명한 기능을 위해서만 사용합니다. 거부하면 해당 연동 기능을 사용할 수 없으며 로컬 편집은 계속 가능합니다.</p><p>기본 브라우저의 Google 인증 화면과 로컬 루프백 콜백을 사용하며, PKCE와 state 확인을 구현합니다. 액세스 토큰·갱신 토큰·가져온 OAuth 클라이언트 설정과 업로드 세션 정보는 앱 데이터 폴더의 <code>credentials</code> 아래에 Windows 사용자 계정에 연결된 DPAPI 암호화 파일로 보관하도록 구현되어 있습니다. 이 정보는 홈페이지로 전송되지 않습니다. 원본으로 가져온 OAuth 설정 JSON은 자동 삭제하지 않으므로 사용자가 별도로 관리해야 합니다.</p><p>토큰 만료가 임박하거나 API 인증이 거부되면 Google 토큰 엔드포인트로 갱신을 요청하고 저장값을 갱신합니다. 갱신이 거부되면 재인증이 필요합니다. 일반 라이브러리 DB·미디어·로그 전체를 암호화한다고 주장하지 않으며, Windows 계정과 PC의 보호는 사용자가 관리해야 합니다.</p>'''),
('로컬 편집 데이터와 보관', '''<p>음악 소스 URL·제목·챕터, 선택 구간·트랙·북마크·메타데이터·편집 설정·작업 기록은 앱 데이터 폴더의 <code>library.sqlite3</code>에 저장됩니다. 가져온 파일과 다운로드한 미디어는 <code>media</code>, 파형과 미리보기는 <code>cache</code>, 앨범아트는 <code>artwork</code>, 진단 기록은 <code>logs</code>에 보관됩니다. MP3·MP4는 사용자가 지정한 출력 폴더에 저장되며 앱 데이터 폴더 밖에 있을 수 있습니다.</p><p>파일·편집 정보와 채널·플레이리스트·업로드 기록은 사용자가 삭제할 때까지 남을 수 있습니다. 자동 만료 삭제 기능은 현재 확인되지 않았습니다. 계정 연결 해제만으로 이 기록이나 미디어가 전부 삭제되지는 않습니다.</p>'''),
('데이터 전송과 외부 서비스', '''<p>별도의 Wavely 운영 서버·클라우드 DB는 없습니다. Google 인증 정보와 계정 데이터는 인증·갱신·권한 철회 및 사용자가 요청한 YouTube API 기능에 필요한 범위에서 사용자의 PC와 Google API 사이에 직접 전송됩니다. 개발자가 이 데이터를 수신하는 서버는 운영하지 않습니다.</p><p>YouTube 가져오기는 외부 도구 yt-dlp를 사용하며, OAuth 업로드 기능과 별개의 경로입니다. 선택한 영상 URL을 처리하면서 YouTube·Google의 미디어 서버/CDN에 접속하고 IP 주소와 요청 정보가 전달될 수 있습니다. 영상 프레임을 가져올 때도 네트워크 요청이 발생합니다. FFmpeg·ffprobe는 편집·변환을 로컬에서 수행합니다. 사용자는 내려받기·편집·업로드 권리와 YouTube 약관을 직접 확인해야 합니다.</p><p>홈페이지는 GitHub Pages에서 호스팅됩니다. 사이트 운영자는 자체 쿠키·분석·광고·추적 스크립트를 추가하지 않지만, GitHub는 호스팅 제공에 필요한 IP 주소 등의 접속 정보를 자체 정책에 따라 처리할 수 있습니다. 이 홈페이지는 Google 계정 로그인이나 토큰을 받지 않습니다.</p><p>Google 사용자 데이터를 판매하거나 광고·프로파일링·범용 AI 모델 학습에 사용하지 않으며, 다른 사용자에게 제공하지 않습니다. 지원 이메일로 직접 보낸 내용은 문의 응대에 사용되며 Gmail을 통해 처리됩니다. 토큰·비밀번호·OAuth 설정 파일을 이메일로 보내지 마세요.</p>'''),
('연결 해제, 권한 철회와 삭제', '''<ol><li><strong>앱에서 연결 해제:</strong> 개발 중인 앱의 <strong>YouTube 업로드 → YouTube 계정</strong>에서 해당 채널의 <strong>연결 해제 및 인증 정보 정리</strong>를 선택합니다. Google 권한 철회를 시도하고 해당 계정의 저장된 토큰과 업로드 세션 인증 정보를 로컬에서 삭제합니다. 네트워크 실패 시 Google 측 철회는 보장되지 않으므로 다음 단계도 확인하세요.</li><li><strong>Google에서 철회:</strong> <a href="https://myaccount.google.com/connections">Google 계정의 서드 파티 연결 관리</a>에서 Wavely를 선택해 액세스 권한을 삭제합니다. 이는 PC의 저장 기록이나 이미 업로드한 영상을 자동 삭제하지 않습니다.</li><li><strong>로컬 정보 전체 삭제:</strong> 진행 중인 작업을 마치고 앱을 완전히 종료합니다. 설정에서 확인한 앱 데이터 폴더(기본 Windows 경로는 <code>%APPDATA%\\app.wavely.desktop</code>, 별도 지정 시 다를 수 있음)를 파일 탐색기에서 삭제합니다. 여기에는 DB와 그 부속 파일, 채널·플레이리스트·업로드 기록, 인증 파일·가져온 OAuth 설정 사본, 캐시·아트·다운로드 미디어·로그가 포함됩니다. 전체 라이브러리가 사라지므로 필요한 파일을 먼저 보관하세요.</li><li><strong>외부 파일과 출력:</strong> 별도 출력 폴더의 MP3·MP4, 앱 외부 원본, 처음 가져온 OAuth JSON 및 사용자가 만든 백업은 자동 삭제되지 않습니다. 파일 탐색기에서 개별 삭제하고 필요한 경우 휴지통도 비웁니다.</li><li><strong>YouTube의 데이터:</strong> 업로드한 영상과 플레이리스트 항목은 <a href="https://studio.youtube.com/">YouTube Studio</a> 또는 YouTube에서 직접 삭제합니다. 앱 연결 해제와 로컬 삭제는 Google에 이미 전송한 영상을 지우지 않습니다.</li></ol><p>현재 앱에는 계정 연결 해제와 별개로 Google 유래 기록만 일괄 삭제하는 전용 기능이나 자동 보관 기간 정리가 확인되지 않았습니다. 앱 데이터 폴더 삭제는 로컬 기록 전체를 삭제하는 방법입니다. 도움이 필요하면 아래 지원 주소로 문의하세요.</p>'''),
('Google·YouTube 정책', '''<p>Wavely의 Google API 데이터 사용·전송은 <a href="https://developers.google.com/terms/api-services-user-data-policy">Google API Services User Data Policy</a>와 해당되는 Limited Use 요건을 준수해야 합니다. 데이터는 위에 공개한 사용자 기능에만 사용하며 판매·광고에 이용하지 않습니다. 이 안내가 Google의 검증 또는 정책 준수 승인을 의미하지는 않습니다.</p><p>YouTube 연동에는 <a href="https://developers.google.com/youtube/terms/api-services-terms-of-service">YouTube API Services Terms of Service</a> 및 <a href="https://developers.google.com/youtube/terms/developer-policies">개발자 정책</a>이 적용되며, 사용자는 <a href="https://www.youtube.com/t/terms">YouTube 서비스 약관</a>에도 구속됩니다. Google의 처리는 <a href="https://policies.google.com/privacy">Google 개인정보처리방침</a>, 홈페이지 호스팅은 <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub 개인정보처리방침</a>을 참고하세요.</p>'''),
('변경과 문의', f'''<p>데이터 처리 방식이나 권한이 변경되면 이 방침의 시행일과 내용을 갱신합니다. 새로운 목적의 Google 데이터 접근에는 필요한 사전 고지와 동의를 거쳐야 합니다.</p><p>운영자·개발자: Qualified4 (Wavely)<br>개인정보·지원 문의: <a href="mailto:{EMAIL}">{EMAIL}</a><br>최종 시행일: <time datetime="{DATE}">{DATE}</time></p>''')]

EN = [
('Scope and operator', f'''<p>Qualified4, the operator and developer of Wavely (contact: <a href="mailto:{EMAIL}">{EMAIL}</a>), explains the handling of data by this personal Windows music editing app and its public information website. The app is not publicly distributed. This website has no user registration, payment features, advertising, analytics or tracking scripts.</p><p>Local editing is implemented. YouTube OAuth, uploads and playlist features are under development and validation. The account-related descriptions below reflect the development code reviewed on the effective date; they do not mean that live Google authorization and uploads have been fully validated.</p>'''),
('Information accessed and purposes', '''<ul><li><strong>Google OAuth:</strong> authorization from the selected Google account to access YouTube APIs. Wavely does not receive your Google password or request Gmail, Contacts or Drive permissions.</li><li><strong>Channel information:</strong> YouTube channel ID and name, connection status and update time, used to display and verify the upload account.</li><li><strong>Playlists:</strong> IDs, titles, visibility, item counts, thumbnail URLs and video membership information, retrieved and stored to select destinations and track playlist additions.</li><li><strong>Selected uploads:</strong> the local MP4 you select, plus its title, description, tags, visibility, audience and other upload settings, sent to YouTube. Unlisted is the default; YouTube may impose a different actual visibility.</li><li><strong>Upload records:</strong> video IDs, channel and track references, local file paths, sizes and hashes, processing and transfer status, errors, timestamps and playlist membership status, stored locally. Resumable upload session information is also processed.</li></ul>'''),
('Permission and credential storage', '''<p>The development code requests one scope: <code>https://www.googleapis.com/auth/youtube.force-ssl</code>, for channel identification, playlist retrieval, video upload and status checks, and adding videos to playlists. This is a broad permission that can view, edit and delete YouTube videos, ratings, comments and captions; it is not read-only or upload-only. Wavely uses it only for the functions disclosed here. Declining prevents connected features, while local editing remains available.</p><p>Authorization uses your default browser and a local loopback callback, with PKCE and state validation implemented. Access tokens, refresh tokens, imported OAuth client configuration and upload session information are stored as Windows user-bound DPAPI encrypted files in the app data folder under <code>credentials</code>. They are not sent to this website. The original imported OAuth JSON file is not automatically deleted and remains your responsibility.</p><p>When a token is near expiry or an API rejects authorization, the app requests a refresh from Google and updates its local credential file. If refresh is rejected, reauthorization is required. General library databases, media and logs are not claimed to be encrypted. You are responsible for protecting your Windows account and computer.</p>'''),
('Local editing data and retention', '''<p>Source URLs, titles and chapters, selected ranges, tracks, bookmarks, metadata, editing settings and job history are stored in <code>library.sqlite3</code> in the app data folder. Imported and downloaded media are in <code>media</code>, waveform and preview caches in <code>cache</code>, album artwork in <code>artwork</code>, and diagnostic records in <code>logs</code>. MP3 and MP4 outputs are saved to your chosen output directories, which may be outside the app data folder.</p><p>Files, edits, channel data, playlists and upload records may remain until you delete them. No automatic expiry cleanup has been confirmed. Disconnecting an account alone does not delete all these records or media.</p>'''),
('Transfers and external services', '''<p>There is no separate Wavely backend or cloud database. Authentication data and Google account data are transmitted directly between your PC and Google APIs only as needed for authorization, refresh, revocation and the YouTube API functions you request. The developer does not operate a server receiving this data.</p><p>YouTube importing uses the external yt-dlp tool through a path separate from OAuth uploads. Processing a selected video URL connects to YouTube and Google media servers or CDNs, which may receive your IP address and request information. Fetching video frames also involves network requests. FFmpeg and ffprobe process media locally. You must verify your rights to download, edit and upload content and the applicable YouTube terms.</p><p>This website is hosted on GitHub Pages. The operator adds no cookies, analytics, advertising or tracking scripts. GitHub may process IP addresses and other access information to provide hosting under its own policy. This website does not receive Google logins or tokens.</p><p>Google user data is not sold or used for advertising, profiling or training general-purpose AI models, or made available to other users. Information you voluntarily send by email is used to answer your inquiry and is handled through Gmail. Do not email tokens, passwords or OAuth configuration files.</p>'''),
('Disconnecting, revocation and deletion', '''<ol><li><strong>Disconnect in the app:</strong> in the development app, open <strong>YouTube 업로드 (YouTube upload) → YouTube 계정 (YouTube account)</strong>, then choose <strong>연결 해제 및 인증 정보 정리 (disconnect and clear credentials)</strong> for the channel. The app attempts Google revocation and removes that account’s locally stored tokens and upload session credentials. Google revocation may fail when the network is unavailable; also check the next step.</li><li><strong>Revoke at Google:</strong> open <a href="https://myaccount.google.com/connections">Google account third-party connections</a>, select Wavely and remove its access. This does not automatically delete local records or uploaded videos.</li><li><strong>Delete all local data:</strong> finish ongoing jobs and fully close the app. In File Explorer, delete the app data folder identified in settings (the default Windows location is <code>%APPDATA%\\app.wavely.desktop</code>; a custom location may differ). This removes the database and associated files, channel, playlist and upload records, credential files including the imported configuration copy, caches, artwork, downloaded media and logs. This deletes the whole library, so retain any files you need first.</li><li><strong>Other files:</strong> outputs in separate MP3/MP4 directories, external originals, the original OAuth JSON and user-created backups are not automatically removed. Delete them separately in File Explorer, and empty the Recycle Bin if needed.</li><li><strong>Data on YouTube:</strong> delete uploaded videos and playlist entries in <a href="https://studio.youtube.com/">YouTube Studio</a> or YouTube. Disconnecting or deleting local data does not delete videos already sent to Google.</li></ol><p>A separate bulk deletion control for Google-derived records and automatic retention cleanup have not been confirmed in the current app. Deleting the app data folder is the way to remove all local records. Contact support below if you need help.</p>'''),
('Google and YouTube policies', '''<p>Wavely’s use and transfer of Google API data must follow the <a href="https://developers.google.com/terms/api-services-user-data-policy">Google API Services User Data Policy</a>, including applicable Limited Use requirements. Data is used only for the disclosed user-facing functions, never sold or used for advertising. This statement does not represent verification or compliance approval by Google.</p><p>The <a href="https://developers.google.com/youtube/terms/api-services-terms-of-service">YouTube API Services Terms of Service</a> and <a href="https://developers.google.com/youtube/terms/developer-policies">Developer Policies</a> apply to YouTube integration. Users are also bound by the <a href="https://www.youtube.com/t/terms">YouTube Terms of Service</a>. See <a href="https://policies.google.com/privacy">Google’s Privacy Policy</a> for Google’s processing, and the <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Privacy Statement</a> for website hosting.</p>'''),
('Changes and contact', f'''<p>We update this policy and its effective date when data handling or permissions change. Access to Google data for a new purpose requires appropriate prior notice and consent.</p><p>Operator and developer: Qualified4 (Wavely)<br>Privacy and support: <a href="mailto:{EMAIL}">{EMAIL}</a><br>Effective date: <time datetime="{DATE}">{DATE}</time></p>''')]

def privacy(sections, english=False):
    title = 'Privacy policy' if english else '개인정보처리방침'
    lead = 'Your music stays in your workspace. Understand what is local, what goes to Google, and how to remove it.' if english else '내 PC에 남는 정보, Google로 전송되는 정보, 그리고 직접 삭제하는 방법을 안내합니다.'
    content = f'<main class="legal" id="main"><span class="eyebrow">Wavely / Privacy</span><h1>{title}</h1><p class="lead">{lead}</p><p class="meta">{("Effective date" if english else "최종 시행일")}: <time datetime="{DATE}">{DATE}</time> · <a href="@@BASE@@'+('privacy/' if english else 'en/privacy/')+'" lang="'+('ko' if english else 'en')+'">'+('한국어' if english else 'Read in English')+'</a></p>'
    content += '<nav class="contents" aria-label="'+('Contents' if english else '목차')+'"><strong>'+('Contents' if english else '목차')+'</strong><ol>'
    content += ''.join(f'<li><a href="#section-{i}">{t}</a></li>' for i,(t,_) in enumerate(sections,1))+'</ol></nav>'
    content += ''.join(f'<section id="section-{i}"><h2>{i:02d}. {t}</h2>{b}</section>' for i,(t,b) in enumerate(sections,1))
    return content+'</main>'

outputs = {
    'index.html': document('Personal Music Curator', home),
    'privacy/index.html': document('개인정보처리방침', privacy(KO), 'privacy'),
    'en/privacy/index.html': document('Privacy policy', privacy(EN, True), 'en/privacy', True),
    '404.html': document('페이지를 찾을 수 없습니다', '<main id="main" class="error"><span class="eyebrow">404</span><h1>페이지를 찾을 수 없습니다.</h1><p><a href="https://wavely.prandiel.dev/">Wavely 홈으로 돌아가기</a></p></main>')
}
for name, html in outputs.items():
    dest = ROOT / name
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(html+'\n', encoding='utf-8')
print(f'Built {len(outputs)} static HTML pages; no runtime JavaScript or dependencies.')
